#!/bin/zsh
# fs-build (wht43 bound-check, 13 Oct 2026): Lean check of GXD.U8XMHH = U8 word (Kothe #869/#870, Boukhalfa #890,
# Capalbo #942) + hub exit frames + mutable sources with 5 centre-source copies kept (k-combine's U8XM) + same-run hosting
# (DaysSky #442 argument; h-L3-build's hosted network Work/XHost), data generated by fs-price.  DFT of every length at
# 1 - 16197705/10^10.
set -e
B=<verify>/checks/wht43/bound-check
F=$B/fs-build; C=~/misc/fft/verify/checks/wht43/colab-run
# 0. Python preflights on the Mac (seconds)
cd $B/fs-price
K=$B/k-combine/pkg/k-combine-u8xm/overlay/Work/GCert/Data
python3 -I tools/indep_audit.py lean/Work/XHost/Data/HU8XMSched.lean $K/Gen/U8XMSched.lean $K/InstU8XM.lean   # host + bank tables, histogram, price
python3 -I tools/audit_slots.py data/words.json U8XM_5cc out/hu8xm_sr.padsa.json                            # hosting assignment
cd $B
python3 -I fs-build/tools/fsb_rate_check.py fs-price/lean/Work/XHost/Data/RateU8XMHHx.lean 16197706 7478 fs-build/in/u8xmhh-profile.json
python3 -I fs-build/tools/fsb_rate_check.py h-L3-build/lean/Work/XHost/Data/RateC588MHHx.lean 15699306 7279   # control
R=k-build/ref/UniformFourier-fd4aeeb2ee4fc729c18d98444fed42fd0529eeeb.lean
bash fs-build/colab/derive_challenges.sh $R 16197705 U8XMHH | cmp - fs-price/lean/Work/FourierU8XMHH/UniformFourierChallenge.lean
bash fs-build/colab/derive_challenges.sh $R 16197706 U8XMHH | cmp - fs-price/lean/Work/FourierU8XMHHNeg/UniformFourierChallenge.lean
# 1. Colab #2: inputs and scripts (own folder /content/work/fs-build; tree = cp -a of k-build's U8XM tree /content/work/kb/B)
$C/ssh2.sh 'mkdir -p /content/work/fs-build/{in,scripts,cc/fresh-bin} /content/work/logs/fs-build'
for f in in/u8xmhh-src.tgz in/xhost-src.tgz in/xhost.sha256 in/HsU8XMHHNeg.lean; do $C/put2.sh $F/$f /content/work/fs-build/in/; done
for f in fsb-setup.sh fsb-build.sh fsb-cmp.sh fsb-chain.sh derive_challenges.sh; do $C/put2.sh $F/colab/$f /content/work/fs-build/scripts/; done
$C/put2.sh $F/colab/jail2.sh /content/work/fs-build/cc/; $C/put2.sh $F/colab/nounix.c /content/work/fs-build/cc/; $C/put2.sh $F/colab/lake /content/work/fs-build/cc/fresh-bin/
$C/ssh2.sh 'cd /content/work/fs-build/cc && gcc -O2 -o nounix nounix.c && chmod 755 jail2.sh nounix fresh-bin/lake'
# 2. setup (waits for k-build's pipeline B, copies its tree, chowns MY copy's .lake to root, hash checks), build, checks,
#    official comparator (positive, negative); each stage only if the previous ended well
$C/ssh2.sh 'tmux -L fsbs new -d -s s "bash /content/work/fs-build/scripts/fsb-setup.sh > /content/work/logs/fs-build/setup.out 2>&1; echo EXIT \$? >> /content/work/logs/fs-build/setup.out"'
$C/ssh2.sh 'tmux -L fsbc new -d -s c "bash /content/work/fs-build/scripts/fsb-chain.sh > /content/work/logs/fs-build/chain.out 2>&1; echo EXIT \$? >> /content/work/logs/fs-build/chain.out"'
# 3. logs back: $C/get2.sh /content/work/logs/fs-build $F/logs/colab
# 4. offline re-creation of the bigospeedrun/verifier check (after one of k-build's verifier chains ended; ~85 min)
for f in fsb-bos-chain.sh fsb-bos-prep.sh fsb-bos-run.sh fsb_submission.py; do $C/put2.sh $F/colab/$f /content/work/fs-build/scripts/; done
$C/ssh2.sh 'cp -a /content/work/kb/bos-verifier /content/work/fs-build/bos-verifier'
$C/ssh2.sh 'tmux -L fsbv new -d -s v "bash /content/work/fs-build/scripts/fsb-bos-chain.sh > /content/work/logs/fs-build/bos-H.out 2>&1; echo EXIT \$? >> /content/work/logs/fs-build/bos-H.out"'
